```javascript
// csvImportAdapter.js — CSV 数据导入适配器: 接收外部 CSV 并生成导入预览页
const express = require('express');
const router = express.Router();

// 将导入的 CSV 文本渲染为预览表格
function renderImportTable(csvText) {
  const rows = csvText.split('\n');
  let html = '<table class="import-preview">';
  for (const row of rows) {
    html += '<tr><td>' + row.trim() + '</td></tr>';
  }
  html += '</table>';
  return html;
}

// 导入适配器入口: 解析请求体中的 csv 字段并返回预览
router.post('/import/preview', (req, res) => {
  const csvText = req.body.csv;
  const tableHtml = renderImportTable(csvText);
  res.send('<html><body>' + tableHtml + '</body></html>');
});

module.exports = router;
```

【静态工具告警】
[HIGH] CWE-79 Cross-site Scripting (Reflected): 导入数据未经中和即写入 HTTP 响应 (csvImportAdapter.js)
  Source: line 18: req.body.csv — POST /import/preview 请求体字段, 攻击者完全可控
  hop 1: line 19 -> renderImportTable(csvText), 污染实参传入渲染函数, line 6 形参无校验接收
  hop 2: line 10: html += '<tr><td>' + row.trim() + '</td></tr>', 污染值直接拼入 HTML 字符串
  hop 3: line 13: return html, 污染 HTML 经返回值扩散至 line 19 的 tableHtml
  Sink: line 20: res.send('<html><body>' + tableHtml + '</body></html>'), 未编码即以 text/html 输出
  修复建议: 在 line 10 拼接前对 row.trim() 做 HTML 实体编码, 或改用自动转义的模板引擎

1. 核实污染源: line 18 的 req.body.csv 位于 router.post('/import/preview') 回调内, 是外部 HTTP 请求体字段, 无白名单、长度或字符校验, 攻击者完全可控, 入口真实可达。
2. 核实 hop1: line 19 将 csvText 作为实参传入 renderImportTable, 与 line 6 形参 csvText 一一对应, 函数内 line 7 的 `split('\n')` 与 line 9 的 for-of 遍历仅做切分, 不消除污染属性。
3. 核实 hop2: line 10 用 + 将 row.trim() 与 '<tr><td>' 拼接, trim 只去首尾空白、不中和尖括号等元字符, 且全文件无 escapeHtml/encode/DOMPurify 调用, 载荷可注入 td 标签上下文。
4. 核实 hop3 与 sink: line 13 return html 经 line 19 赋值给 tableHtml, line 20 res.send 将其作为响应体输出, Express 对字符串响应默认 Content-Type 为 text/html, 浏览器解析时执行内嵌脚本, sink 真实可达。
5. 结论: 传播链每一跳均有真实代码对应且无任何有效防御, 例如 csv 行为 <img src=x onerror=alert(1)> 即可在预览页触发脚本执行, 判定该告警为真阳性。

