```java
package com.mail.template;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

@RestController
public class MailTemplateController {

    private final TemplateRenderer renderer = new TemplateRenderer();

    @GetMapping("/mail/template/preview")
    public String preview(@RequestParam("tpl") String tplName,
                          @RequestParam("uid") String uid) throws IOException {
        String body = renderer.load(tplName);
        return renderer.render(body, uid);
    }
}

class TemplateRenderer {

    String load(String name) {
        return "Dear " + name + ", your bill is ready.";
    }

    String render(String body, String uid) throws IOException {
        String cmd = "tplrender --uid " + uid + " --inline " + body;
        Process p = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", cmd});
        return new String(p.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
    }
}
```

【静态工具告警】
[告警] MailTemplateController.java — rule=java_command_injection (CWE-78 OS Command Injection) | 置信度: 0.93
Source: line 16: uid — HTTP 入口 GET /mail/template/preview 的 @RequestParam 外部输入，端点公开未鉴权，可达
Hop1: line 16 uid -> line 18 作为第二实参传入 renderer.render(body, uid)
Hop2: line 18 -> line 28 形参 String uid 接收污点 -> line 29 拼接进命令串 cmd
Sink: line 30: Runtime.getRuntime().exec — cmd 经 /bin/sh -c 整体交 shell 解释，可注入任意命令
Note: line 15 tplName 经 line 17 load 返回值 body 亦汇入同一 sink（次级流）
