app.post('/api/orders/export-invoice', (req, res) => {
  const orderId = req.body.orderId;
  const operator = req.body.operator || 'system';
  jobQueue.push({ orderId: orderId, operator: operator });
  res.json({ status: 'queued' });
});

// 后台 worker: 每秒轮询队列执行导出
setInterval(() => {
  while (jobQueue.length > 0) {
    const job = jobQueue.shift();
    runExportJob(job);
  }
}, 1000);

function runExportJob(job) {
  const filePath = path.join(INVOICE_DIR, job.orderId);
  const content = fs.readFileSync(filePath);
  console.log('[export] operator=' + job.operator + ' file=' + filePath + ' size=' + content.length);
}

app.listen(8080);
