<?php
// SessionManager.php —— 会话管理组件：查看指定会话的运行日志
class SessionManager {
    private $storageDir = '/var/www/app/storage/sessions/';

    public function handleViewSessionLog() {
        $sessionId = $_GET['session_id'];
        $action = $_GET['action'] ?? 'view';

        if ($action !== 'view') {
            return false;
        }

        $logPath = $this->buildLogPath($sessionId);
        return $this->readSessionLog($logPath);
    }

    private function buildLogPath($sid) {
        return $this->storageDir . $sid;
    }

    private function readSessionLog($path) {
        if (!file_exists($path)) {
            return 'log not found';
        }
        return file_get_contents($path);
    }
}

$manager = new SessionManager();
$manager->handleViewSessionLog();
