package com.example.render;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class TemplateRenderer {

    private static final Path TEMPLATE_BASE = Paths.get("/var/app/templates");

    /** 渲染入口: 按 locale 与模板名加载模板文件并替换占位符 */
    public String renderPage(String templateName, String locale) throws IOException {
        String relative = locale + "/" + templateName;
        Path templatePath = TEMPLATE_BASE.resolve(relative);
        if (!Files.exists(templatePath)) {
            templatePath = TEMPLATE_BASE.resolve(templateName);
        }
        String content = new String(Files.readAllBytes(templatePath), StandardCharsets.UTF_8);
        return content.replace("{{user}}", currentUser());
    }

    private String currentUser() {
        return "guest";
    }
}
