// email-template-service.js —— 邮件模板渲染与发送服务
const express = require('express');
const { exec } = require('child_process');
const app = express();
app.use(express.json());

app.post('/api/send-template', (req, res) => {
  const templateName = req.body.template;
  const recipient = req.body.to;
  const locale = req.query.locale || 'zh-CN';

  // 拼接模板路径并调用外部渲染器
  const templatePath = './templates/' + templateName + '.mjml';
  const renderCmd = 'mjml ' + templatePath + ' -o /tmp/render_' + locale + '.html';

  exec(renderCmd, (err) => {
    if (err) {
      return res.status(500).json({ error: 'render failed' });
    }
    // 渲染成功后通过 sendmail 投递
    const sendCmd = 'sendmail -f noreply@corp.com ' + recipient;
    exec(sendCmd, (err2) => {
      if (err2) {
        return res.status(500).json({ error: 'send failed' });
      }
      res.json({ status: 'sent', template: templateName });
    });
  });
});

app.listen(8080);
```

