package com.acme.report.export;

import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

public class ReportExportService {

    // 报表导出服务：解析客户端上传的 XML 报表模板，抽取列配置并导出 CSV
    public String exportReport(HttpServletRequest request, HttpServletResponse response) throws Exception {
        String templateXml = request.getParameter("template");
        byte[] xmlBytes = templateXml.getBytes(StandardCharsets.UTF_8);

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(new ByteArrayInputStream(xmlBytes));

        NodeList columns = doc.getElementsByTagName("column");
        StringBuilder csv = new StringBuilder();
        for (int i = 0; i < columns.getLength(); i++) {
            csv.append(columns.item(i).getTextContent()).append(",");
        }
        response.setContentType("text/csv");
        return csv.toString();
    }
}
```

